import{At as e,F as t,L as n,M as r,R as i,et as a}from"./chunks/framework.Bs4wm_X5.js";import{t as o}from"./chunks/ChromaProfileCollection.C1faLyZp.js";import{t as s}from"./chunks/chords.C-1lNo7f.js";var c=JSON.parse(`{"title":"Tetrads","description":"All musically meaningful combinations of 4 notes","frontmatter":{"title":"Tetrads","description":"All musically meaningful combinations of 4 notes","cover":"kelly-sikkema.jpg","date":"2021-09-10T00:00:00.000Z"},"headers":[],"relativePath":"theory/chords/tetrads/index.md","filePath":"theory/chords/tetrads/index.md","lastUpdated":1789463788000}`),l=Object.assign({name:`theory/chords/tetrads/index.md`},{setup(c){let{tetrads:l}=s;return(s,c)=>{let u=o;return a(),t(`div`,null,[c[0]||=r(`h2`,{id:`seventh-chords`,tabindex:`-1`},[n(`Seventh chords `),r(`a`,{class:`header-anchor`,href:`#seventh-chords`,"aria-label":`Permalink to “Seventh chords”`},`​`)],-1),c[1]||=r(`p`,null,`A seventh chord is a chord consisting of a triad plus a note forming an interval of a seventh above the chord's root. When not otherwise specified, a "seventh chord" usually means a dominant seventh chord: a major triad together with a minor seventh. However, a variety of sevenths may be added to a variety of triads, resulting in many different types of seventh chords.`,-1),c[2]||=r(`p`,null,`In its earliest usage, the seventh was introduced solely as an embellishing or nonchord tone. The seventh destabilized the triad, and allowed the composer to emphasize movement in a given direction. As time passed and the collective ear of the western world became more accustomed to dissonance, the seventh was allowed to become a part of the chord itself, and in some modern music, jazz in particular, nearly every chord is a seventh chord. Additionally, the general acceptance of equal temperament during the 19th century reduced the dissonance of some earlier forms of sevenths.`,-1),c[3]||=r(`p`,null,`Most textbooks name these chords formally by the type of triad and type of seventh; hence, a chord consisting of a major triad and a minor seventh above the root is referred to as a major/minor seventh chord. When the triad type and seventh type are identical (i.e. they are both major, minor, or diminished), the name is shortened. For instance, a major/major seventh is generally referred to as a major seventh. This rule is not valid for augmented chords: since the augmented/augmented chord is not commonly used, the abbreviation augmented is used for augmented/minor, rather than augmented/augmented. Additionally, half-diminished stands for diminished/minor, and dominant stands for major/minor. When the type is not specified at all, the triad is assumed to be major, and the seventh is understood as a minor seventh (e.g. a "C" chord is a "C major triad", and a "C7" chord is a "C major/minor seventh chord", also known as a "C dominant seventh chord").`,-1),c[4]||=r(`h2`,{id:`tertian`,tabindex:`-1`},[n(`Tertian `),r(`a`,{class:`header-anchor`,href:`#tertian`,"aria-label":`Permalink to “Tertian”`},`​`)],-1),c[5]||=r(`p`,null,`The most common chords are tertian, constructed using a sequence of major thirds (spanning 4 semitones) and/or minor thirds (3 semitones). Since there are 3 third intervals in a seventh chord (4 notes) and each can be major or minor, there are 8 possible combinations, however, only seven of them are commonly found in western music. The augmented augmented seventh chord, defined by a root, a major third, an augmented fifth, and an augmented seventh (i.e., a sequence of 3 major thirds, such as C–E–G♯–B♯), is a rarely used tertian seventh chord. The reason is that the augmented seventh interval is enharmonically equivalent to one entire octave (in equal temperament, 3 major thirds = 12 semitones = 1 octave) and is hence perfectly consonant with the chord root.`,-1),i(u,{collection:e(l).tertian},null,8,[`collection`]),c[6]||=r(`hr`,null,null,-1),c[7]||=r(`h2`,{id:`non-tertian`,tabindex:`-1`},[n(`Non-tertian `),r(`a`,{class:`header-anchor`,href:`#non-tertian`,"aria-label":`Permalink to “Non-tertian”`},`​`)],-1),c[8]||=r(`p`,null,`Seventh chords can also be constructed using augmented or diminished thirds. These chords are not tertian and can be used in non-tertian harmony. There are many (mathematically, 64) chords that can be built, however, only few of them are used.`,-1),i(u,{collection:e(l).nontertian},null,8,[`collection`])])}}});export{c as __pageData,l as default};